@bot.tree.command(name="kadro", description="Arctic klan kadrosunu rollere göre gösterir.")
@app_commands.guild_only()
async def kadro(interaction: discord.Interaction) -> None:
    guild = interaction.guild
    if guild is None:
        await interaction.response.send_message("Bu komut sadece sunucuda kullanılabilir.", ephemeral=True)
        return

    if not guild.chunked:
        try:
            await guild.chunk(cache=True)
        except (discord.ClientException, discord.HTTPException):
            pass

    role_sections = [
        ("🎯 Roamer", "Roamer"),
        ("🏗️ Builder", "Builder"),
        ("⛏️ Farmer", "Farmer"),
    ]

    embed = discord.Embed(
        title="Arctic Klan Kadrosu",
        description="Kadro, Discord'da verilen rollere göre otomatik güncellenir.",
        colour=discord.Colour.blue(),
    )

    unique_members: set[int] = set()
    for role_name, label in role_sections:
        role = find_role(guild, role_name)
        members = [] if role is None else sorted(
            (member for member in role.members if not member.bot),
            key=lambda member: member.display_name.casefold(),
        )
        unique_members.update(member.id for member in members)

        if members:
            value = "\n".join(f"• {member.mention}" for member in members)
            if len(value) > 1000:
                value = value[:997] + "..."
        else:
            value = "Henüz kimse yok."

        embed.add_field(
            name=f"{label} — {len(members)}",
            value=value,
            inline=False,
        )

    embed.set_footer(text=f"Toplam kadro: {len(unique_members)} kişi")
    await interaction.response.send_message(embed=embed)


